syntax = "proto3";

package telemetry;

service TelemetryService {
  // Unary RPC
  rpc GetSystemStatus (StatusRequest) returns (StatusResponse);

  // Server Streaming RPC
  rpc StreamMetrics (MetricsRequest) returns (stream MetricData);

  // Client Streaming RPC
  rpc UploadLogs (stream LogChunk) returns (UploadSummary);

  // Bidirectional Streaming RPC
  rpc InteractiveDiagnostics (stream DiagnosticCommand) returns (stream DiagnosticEvent);
}

message StatusRequest { string node_id = 1; }
message StatusResponse { string status = 1; int64 uptime_seconds = 2; }
message MetricsRequest { string node_id = 1; int32 interval_seconds = 2; }
message MetricData { int64 timestamp = 1; double cpu_usage = 2; double memory_usage = 3; }
message LogChunk { string node_id = 1; bytes data = 2; }
message UploadSummary { int64 total_bytes_received = 1; bool success = 2; }
message DiagnosticCommand { string command = 1; }
message DiagnosticEvent { int64 timestamp = 1; string output = 2; }
